import { DatabaseSync } from 'node:sqlite';
function main(): void {
  try { new (DatabaseSync as any)(); } catch (e: any) { console.log(e.name, e.code, e.message); }
  try { new (DatabaseSync as any)(':memory:', 5); } catch (e: any) { console.log(e.name, e.code, e.message); }
  try { new DatabaseSync(':memory:', { readOnly: 'yes' } as any); } catch (e: any) { console.log(e.name, e.code, e.message); }
  try { new DatabaseSync(':memory:').exec(42 as any); } catch (e: any) { console.log(e.name, e.code, e.message); }
}
